import SwiftUI

@main
struct HostApp: App {
    var body: some Scene {
        WindowGroup {
            Text("Host")
        }
    }
}

import XCTest

final class BlueskyUITests: XCTestCase {
    func testBluesky() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let window = app.windows.element(boundBy: 0)
        XCTAssertTrue(window.waitForExistence(timeout: 15))

        let env = ProcessInfo.processInfo.environment
        let stage = env["STAGE"] ?? "A"

        if stage == "A" {
            let searchField = app.textFields.firstMatch
            if !searchField.waitForExistence(timeout: 3) {
                window.coordinate(withNormalizedOffset: CGVector(dx: 0.31, dy: 0.937)).tap()
                XCTAssertTrue(searchField.waitForExistence(timeout: 10), "search field did not appear")
            }
            searchField.tap()
            searchField.typeText("news")
            searchField.typeText(XCUIKeyboardKeyReturn.rawValue)
            Thread.sleep(forTimeInterval: 4)
        } else {
            let dx = Double(env["FEEDS_DX"] ?? "0.7")!
            let dy = Double(env["FEEDS_DY"] ?? "0.22")!
            Thread.sleep(forTimeInterval: 1)
            window.coordinate(withNormalizedOffset: CGVector(dx: dx, dy: dy)).tap()
            Thread.sleep(forTimeInterval: 3)
        }
    }
}

