import XCTest

final class BlueskyUITests: XCTestCase {
    func testBluesky() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        Thread.sleep(forTimeInterval: 3)

        let env = ProcessInfo.processInfo.environment
        let stage = env["STAGE"] ?? "A"

        if stage == "A" {
            var fieldExists = false
            for _ in 0..<3 {
                if app.textFields.firstMatch.exists { fieldExists = true; break }
                Thread.sleep(forTimeInterval: 1)
            }
            if !fieldExists {
                app.coordinate(withNormalizedOffset: CGVector(dx: 0.31, dy: 0.937)).tap()
                Thread.sleep(forTimeInterval: 2)
            }
            let field = app.textFields.firstMatch
            XCTAssertTrue(field.waitForExistence(timeout: 10), "search field did not appear")
            field.tap()
            Thread.sleep(forTimeInterval: 1)
            field.typeText("news")
            field.typeText("\n")
            Thread.sleep(forTimeInterval: 4)
        } else {
            let dx = Double(env["FEEDS_DX"] ?? "0.7")!
            let dy = Double(env["FEEDS_DY"] ?? "0.22")!
            Thread.sleep(forTimeInterval: 1)
            app.coordinate(withNormalizedOffset: CGVector(dx: dx, dy: dy)).tap()
            Thread.sleep(forTimeInterval: 3)
        }
    }
}

